    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == value and not visited[i][j]:
                # BFS from this cell
                comp = []
                queue = deque([(i, j)])
                visited[i][j] = True

                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
